from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Button, Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
left_wheel = Motor(Port.F, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.B, Direction.CLOCKWISE)
Lybbert_green = DriveBase(left_wheel, right_wheel, 56, 140)
Left_motor = Motor(Port.E, Direction.CLOCKWISE)
Right_motor = Motor(Port.A, Direction.CLOCKWISE)
Left_color_sensor = ColorSensor(Port.D)
Right_color_sensor = ColorSensor(Port.C)
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.Y)

async def Eldertree_():
    await wait(0)
    # Elder tree +
    Lybbert_green.settings(straight_acceleration=250)
    await Lybbert_green.straight(750)
    while not await Left_color_sensor.reflection():
        await wait(0)
    await Lybbert_green.straight(10)
    Lybbert_green.settings(turn_rate=50)
    await Lybbert_green.turn(55)
    await Right_motor.run_angle(500, 20)
    await Lybbert_green.straight(50)
    await Right_motor.run_angle(500, -25)
    await prime_hub.speaker.beep(500, 100)
    await Right_motor.run_angle(90, 45)
    await Lybbert_green.straight(30)
    await Right_motor.run_angle(500, -40)
    Lybbert_green.settings(straight_speed=200)
    await Lybbert_green.arc(200, angle=-120, then=Stop.NONE)
    await Lybbert_green.straight(-400)

async def Reseed():
    await wait(0)
    # Right seed
    # 1st black right
    await Lybbert_green.arc(-100, angle=65)
    await Lybbert_green.straight(385)
    await Right_motor.run_angle(500, 40)
    Lybbert_green.settings(straight_speed=100)
    await Lybbert_green.straight(-500)

async def Seed():
    await wait(0)
    # Start 5 squares from outside on wall
    # Seed
    Lybbert_green.settings(straight_acceleration=250)
    await Lybbert_green.straight(595)
    await Lybbert_green.turn(20)
    await Lybbert_green.turn(-10)
    await Right_motor.run_angle(250, 20)
    await Lybbert_green.straight(-600)

async def subtask():
    await wait(1000)
    await Lybbert_green.straight(-60)

async def Eldertree():
    await wait(0)
    # Elder Tree Support - start on 2nd black line from right
    Lybbert_green.settings(straight_acceleration=250)
    await Lybbert_green.straight(750)
    while not await Left_color_sensor.reflection():
        await wait(0)
    await Lybbert_green.straight(10)
    Lybbert_green.settings(turn_rate=50)
    await Lybbert_green.turn(63)
    await Lybbert_green.straight(30)
    await multitask(
        Right_motor.run_angle(750, 44),
        subtask(),
    )
    await Right_motor.run_angle(500, -10)
    await Lybbert_green.turn(-75)
    await Lybbert_green.arc(700, angle=-180)

async def Bug_drop():
    await wait(0)
    # Bug drop
    Lybbert_green.settings(straight_speed=300)
    await Lybbert_green.arc(1100, angle=43)
    await Lybbert_green.straight(10)
    await Right_motor.run_angle(500, -750)
    Lybbert_green.settings(straight_speed=500)
    await Lybbert_green.arc(1100, angle=-45)

async def Seed_drop():
    await wait(0)
    # Seed drop - 2nd black line from left
    Lybbert_green.settings(straight_speed=500)
    await Lybbert_green.straight(320)
    await Right_motor.run_angle(500, -1000)
    await Lybbert_green.straight(-320)

async def main():
    while not Button.LEFT in prime_hub.buttons.pressed():
        await wait(0)
    await wait(200)
    await Bug_drop()
    # 2nd black line from left
    while not Button.LEFT in prime_hub.buttons.pressed():
        await wait(0)
    await wait(200)
    await Eldertree_()
    # 2nd black on right
    while not Button.LEFT in prime_hub.buttons.pressed():
        await wait(0)
    await wait(200)
    await Seed_drop()


run_task(main())